    58→    --radius-sm: 0.25rem;
    59→    --radius-md: 0.5rem;
    60→    --radius-lg: 1rem;
    61→
    62→    /* Z-Index Scale */
    63→    --z-dropdown: 100;
    64→    --z-sticky: 200;
    65→    --z-fixed: 300;
    66→    --z-modal: 400;
    67→    --z-overlay: 500;
    68→}
